const byJapanese=new Map(translations);
const byEnglish=new Map(translations.map(([ja,en])=>[en,ja]));
let language=globalThis.localStorage?.getItem('pve.language')==='en'?'en':'ja';

export function currentLanguage(){return language}
export function setLanguage(next){language=next==='en'?'en':'ja';globalThis.localStorage?.setItem('pve.language',language);if(globalThis.document)document.documentElement.lang=language;return language}
function exactTranslation(body,target){if(target==='en'){const placement=body.match(/^([VA]\d)へ配置$/),visibility=body.match(/^(F\/T\d|V\d)を非表示$/),mute=body.match(/^(A\d)をミュート$/),volume=body.match(/^([VA]\d)の音量$/);if(placement)return`Place on ${placement[1]}`;if(visibility)return`Hide ${visibility[1]}`;if(mute)return`Mute ${mute[1]}`;if(volume)return`${volume[1]} volume`;return byJapanese.get(body)??body}const placement=body.match(/^Place on ([VA]\d)$/),visibility=body.match(/^Hide (F\/T\d|V\d)$/),mute=body.match(/^Mute (A\d)$/),volume=body.match(/^([VA]\d) volume$/);if(placement)return`${placement[1]}へ配置`;if(visibility)return`${visibility[1]}を非表示`;if(mute)return`${mute[1]}をミュート`;if(volume)return`${volume[1]}の音量`;return byEnglish.get(body)??body}
export function translate(value,target=language){const source=String(value??''),match=source.match(/^(\s*)([\s\S]*?)(\s*)$/),lead=match?.[1]||'',body=match?.[2]||'',trail=match?.[3]||'',decorated=body.match(/^([＋✧⠿]\s+)(.+)$/);if(decorated){const translated=translate(decorated[2],target);if(translated!==decorated[2])return lead+decorated[1]+translated+trail}const direct=exactTranslation(body,target);if(direct!==body)return lead+direct+trail;const sentences=target==='en'?body.match(/[^。！？]+[。！？]?/g)||[]:body.match(/\s*[^.!?]+[.!?]?/g)?.map(part=>part.trim())||[];if(sentences.length>1){const translated=sentences.map(sentence=>exactTranslation(sentence,target));if(translated.some((part,index)=>part!==sentences[index]))return lead+translated.join(target==='en'?' ':'')+trail}return source}
export function translateDOM(root=document){
 document.documentElement.lang=language;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){if(node.parentElement?.closest('[data-no-i18n],.media-name,.text-chip,.text-item,.project-option'))continue;const value=translate(node.nodeValue);if(value!==node.nodeValue)node.nodeValue=value}
 for(const element of root.querySelectorAll?.('[title],[aria-label],[placeholder]')||[])for(const name of['title','aria-label','placeholder'])if(element.hasAttribute(name))element.setAttribute(name,translate(element.getAttribute(name)));
}
